{
  "implementation": "def solve(case):
    # Extract data from case payload
    payload = case['payload']
    min_cluster_size = payload['min_cluster_size']
    clusters_list = payload['clusters']
    parent_map = payload['parent']

    # Build cluster lookup and tree
    clusters = {}
    for c in clusters_list:
        cid = c['cluster_id']
        clusters[cid] = {
            'size': c['size'],
            'birth': c['birth_lambda'],
            'exits': sorted(c['point_exit_lambdas']),
            'children': []
        }
    # Build children lists from parent map
    roots = []
    for cid, pid in parent_map.items():
        if pid is None:
            roots.append(cid)
        else:
            clusters[pid]['children'].append(cid)

    # Compute stability for each cluster
    def compute_stability(cid):
        info = clusters[cid]
        n = info['size']
        # If no point_exit_lambdas provided, assume infinite lambda (cluster never dies)
        if not info['exits']:
            return float('inf')
        # Stability = sum of (exit - birth) for all points
        sum_exits = sum(info['exits'])
        return sum_exits - n * info['birth']

    # Compute stabilities with memoization
    stabilities = {}
    def get_stability(cid):
        if cid not in stabilities:
            stabilities[cid] = compute_stability(cid)
        return stabilities[cid]

    # Compute total child stability sum for each node
    child_stability_sum = {}
    def compute_child_sum(cid):
        total = 0.0
        for child in clusters[cid]['children']:
            total += get_stability(child) + compute_child_sum(child)
        return total

    for cid in clusters:
        child_stability_sum[cid] = compute_child_sum(cid)

    # Select clusters by traversing tree from roots
    selected = []
    def traverse(cid):
        info = clusters[cid]
        parent_stability = get_stability(cid)
        child_sum = child_stability_sum[cid]
        if parent_stability > child_sum + 1e-12:  # numeric tolerance
            selected.append(cid)
        else:
            for child in info['children']:
                traverse(child)

    for root in roots:
        traverse(root)

    return {'selected_clusters': selected}"
}
